/**
 * Removes an issue's own document and every comment document beneath it. The
 * comment side is selected by the comment table, not by the index, so comments
 * are caught whether or not they were ever indexed.
 */
export async function deleteSearchDocumentsForIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const db = getDb();
  const commentIds = db
    .select({ id: comments.id })
    .from(comments)
    .where(
      and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
    );

  db.delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        or(
          and(
            eq(searchIndex.subjectKind, "issue"),
            eq(searchIndex.subjectId, issueId),
          ),
          and(
            eq(searchIndex.subjectKind, "comment"),
            inArray(searchIndex.subjectId, commentIds),
          ),
        ),
      ),
    )
    .run();
}

/**
 * Removes a project's document plus every issue and comment document beneath
 * it, whether those issues were archived with the project or earlier.
 */
export async function deleteSearchDocumentsForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const db = getDb();
  const issueIds = db
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    );
  const commentIds = db
    .select({ id: comments.id })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        inArray(comments.issueId, issueIds),
      ),
    );

  db.delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        or(
          and(
            eq(searchIndex.subjectKind, "project"),
            eq(searchIndex.subjectId, projectId),
          ),
          and(
            eq(searchIndex.subjectKind, "issue"),
            inArray(searchIndex.subjectId, issueIds),
          ),
          and(
            eq(searchIndex.subjectKind, "comment"),
            inArray(searchIndex.subjectId, commentIds),
          ),
        ),
      ),
    )
    .run();
}

/** Drops every document an organization has. Used before a full rebuild. */
export async function deleteSearchDocumentsForOrg(orgId: OrgId): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .run();
}

