/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { indexProjectTree } from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";

/** Rows read per page while walking the org's projects. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Rebuilds one tenant's index from scratch. Every existing entry for the org
 * is dropped first, so stale rows cannot survive, and then each live project is
 * re-indexed with its live issues and comments. Other tenants' entries are never
 * read or written. Archived projects are not walked at all, and the index
 * writers reject anything beneath them.
 *
 * Scoped to a single org on purpose: a full-fleet reindex is a sequence of
 * these, so one slow tenant cannot stall the rest.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    await searchRepo.deleteSearchDocumentsForOrg(orgId);

    let cursor: string | null = null;
    do {
      const projects = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor,
        includeArchived: false,
      });

      for (const project of projects.items) {
        try {
          await indexProjectTree(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
      cursor = projects.nextCursor;
    } while (cursor !== null);
  });
}

